urlset:
{% assign collections = site.collections | where_exp:'collection','collection.output != false' %}
{% for collection in collections %}
  {% assign docs = collection.docs | where_exp:'doc','doc.sitemap != false' | where_exp:'doc','doc.not_running_related != true' %}
  {% for doc in docs %}

      {{ doc.url | replace:'/index.html','/' | absolute_url | xml_escape }}
      {% if doc.last_modified_at or doc.date %}
        {{ doc.last_modified_at | default: doc.date | date_to_xmlschema }}
      {% endif %}

  {% endfor %}
{% endfor %}

{% assign episode_pages = site.pages | where_exp: "item", "item.category == 'podcast_episode'" %}
{% for page in episode_pages %}
  {% if page.sitemap != false %}

    {{ page.url | replace:'/index.html','/' | absolute_url | xml_escape }}
    {% if page.published_at or page.date %}
      {{ page.published_at | default: page.date | date_to_xmlschema }}
    {% endif %}

  {% endif %}
{% endfor %}

{% assign sitemap_page_paths = "/,/about/,/latest-episodes/,/runners-picks/,/llms.txt" | split: "," %}
{% for sitemap_path in sitemap_page_paths %}
  {% assign page = site.pages | where: "url", sitemap_path | first %}
  {% if page and page.sitemap != false %}

    {{ page.url | replace:'/index.html','/' | absolute_url | xml_escape }}
    {% if page.last_modified_at %}
      {{ page.last_modified_at | date_to_xmlschema }}
    {% endif %}

  {% endif %}
{% endfor %}
